  }
  * { box-sizing: border-box; }
  html, body { margin: 0; padding: 0; background: var(--bg); color: var(--ink);
    font-family: 'Helvetica Neue', 'Inter', 'Arial', sans-serif; }
  /* A0 portrait at ~96dpi: 2384 x 3370. We use 1600x2263 (scale 0.671) and
     render via Playwright at deviceScaleFactor=2 to produce ~3200x4526 px PNG. */
