  /* Custom SVG chart wrapper */
  .chart-wrap { width: 100%; height: 560px; }

  /* Two-column comparison row */
  .row {
    display: grid; grid-template-columns: 1fr 1fr; gap: 22px; margin-bottom: 26px;
  }
  .panel {
    background: var(--paper); border: 1px solid var(--line);
