  .panel.dark .section-label { color: #7fcfe0; }
  .panel.dark .section-title { color: #fff; }
  .panel.dark .section-desc { color: #cfdde7; }

  .compare-grid {
    display:grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-top: 14px;
  }
  .ccard { padding: 18px; border-radius: 4px; }
  .ccard.cool { background: rgba(255,255,255,0.08); border:1px solid rgba(255,255,255,0.18); }
  .ccard.warm { background: rgba(193,39,45,0.95); }
  .ccard h4 { margin:0 0 10px 0; font-size: 13px; letter-spacing:1.5px; text-transform:uppercase; color:#fff; opacity:0.85;}
