    padding-top: 14px;
  }
  .footer .src { letter-spacing: 1px; }
  .footer .doi { font-family: 'Courier New', monospace; }
</style>
</head>
<body>
<div class="poster">

  <div class="header">
    <div>
      <div class="eyebrow">Climate Science · Marine Proxy Reconstruction</div>
      <h1>300 Years of Sclerosponge Thermometry Reveal<br/>Global Warming Has <span class="accent">Already Exceeded 1.5 °C</span></h1>
      <div class="subtitle">Sr/Ca-based ocean temperature records from Caribbean sclerosponges extend the climate baseline back to ~1700 CE, exposing ~0.5 °C of warming hidden before the conventional 1850–1900 instrumental reference period.</div>
    </div>
    <div class="venue">
      <div class="badge">AGU · Nature Climate Change</div>
      <div>Symposium 2026 · Poster Session</div>
      <div>Marine Geochemistry &amp; Paleoclimate</div>
    </div>
  </div>

  <div class="stats">
    <div class="stat"><div class="v">~300 yrs</div><div class="l">Record Length</div></div>
    <div class="stat"><div class="v">~0.5 °C</div><div class="l">Hidden Pre-1850 Warming</div></div>
    <div class="stat"><div class="v">&gt;1.5 °C</div><div class="l">Total Warming (true baseline)</div></div>
    <div class="stat"><div class="v">~1.2 °C</div><div class="l">IPCC AR6 Estimate (1850–1900)</div></div>
    <div class="stat"><div class="v">r² &gt; 0.9</div><div class="l">Sr/Ca–SST Calibration</div></div>
  </div>

  <div class="centerpiece">
    <div class="section-label">Centerpiece · 300-year reconstruction</div>
    <h2 class="section-title">Sea-Surface Temperature Anomaly, 1700 – 2023</h2>
    <p class="section-desc">Reconstructed SST anomaly (°C) relative to the true pre-industrial mean (1700–1790). The conventional IPCC 1850–1900 baseline (dashed) sits ~0.5 °C above true pre-industrial — and the 1.5 °C Paris threshold is crossed in the early 2020s.</p>
    <div class="chart-wrap">
      <svg id="tempchart" viewBox="0 0 1480 540" preserveAspectRatio="none" style="width:100%;height:100%;"></svg>
    </div>
  </div>

  <div class="row">
    <div class="panel dark">
      <div class="section-label">Key Finding</div>
      <h2 class="section-title">The Hidden 0.5 °C</h2>
      <p class="section-desc">The 1850–1900 reference period was <em>not</em> truly pre-industrial — early industrialisation had already warmed the oceans.</p>
      <div class="compare-grid">
        <div class="ccard cool">
          <h4>IPCC AR6 (1850–1900 baseline)</h4>
          <div class="num">1.2<span class="unit"> °C</span></div>
          <div class="note">Reported warming relative to the standard instrumental reference period.</div>
        </div>
        <div class="ccard warm">
          <h4>Sclerosponge (1700–1790 baseline)</h4>
          <div class="num">1.7<span class="unit"> °C</span></div>
          <div class="note">Total warming from a true pre-industrial baseline — already past 1.5 °C.</div>
        </div>
      </div>
      <div class="delta"><b>+0.5 °C</b> &nbsp;of anthropogenic warming occurred <em>before</em> the conventional baseline begins, systematically under-reported by instrumental records.</div>
    </div>

    <div class="panel">
      <div class="section-label">Background</div>
      <h2 class="section-title">Why Sclerosponges?</h2>
      <p class="section-desc">Long-lived tropical reef organisms whose aragonite skeletons archive ambient SST through Sr/Ca chemistry — independent of instrumental networks.</p>
      <ul class="why-list">
        <li>
          <div class="ico">Sr</div>
          <div><div class="t">Sr/Ca thermometer</div><div class="d">Strontium-to-calcium ratios in aragonite track ambient sea-surface temperature with sub-annual fidelity (calibrated r² &gt; 0.9 vs. instrumental SST since 1960).</div></div>
        </li>
        <li>
          <div class="ico">∞</div>
          <div><div class="t">Centuries of continuous growth</div><div class="d">Slow, uninterrupted skeletal accretion produces unbroken annual-resolution records spanning ~300 years — extending well beyond instrumental coverage.</div></div>
        </li>
        <li>
          <div class="ico">🌊</div>
          <div><div class="t">Independent of weather stations</div><div class="d">Caribbean reef sites at 33–91 m depth capture large-scale tropical SST variability without inheriting instrumental-network biases or coverage gaps.</div></div>
        </li>
      </ul>
    </div>
  </div>

  <div class="row">
    <div class="panel" style="grid-column: 1 / -1;">
      <div class="impl-grid">
        <div>
          <div class="section-label">Implications</div>
          <h2 class="section-title">Policy &amp; Climate-Target Consequences</h2>
          <ul class="impl-list">
            <li><b>1.5 °C is already breached</b> when measured against a true pre-industrial baseline, not merely approached as instrumental records suggest.</li>
            <li><b>Remaining carbon budget for 1.5 °C is effectively zero</b> under the sclerosponge-informed reference period.</li>
            <li><b>2.0 °C guardrail is closer than reported</b> — only ~0.3 °C of additional warming is available, not the conventionally cited ~0.8 °C.</li>
            <li><b>Baseline transparency is critical</b>: how "pre-industrial" is defined materially changes perceived progress against Paris Agreement targets.</li>
          </ul>
        </div>
        <div>
          <div class="section-label">Methods</div>
          <h2 class="section-title">Data &amp; Validation</h2>
          <div class="methods">
            <p>Sclerosponge specimens were collected from Caribbean reef environments and analysed for Sr/Ca via ICP-OES, then calibrated against co-located instrumental SST records.</p>
            <div class="kv">
              <div class="k">Site</div><div class="v">Caribbean reefs, 33–91 m depth</div>
              <div class="k">Proxy</div><div class="v">Sr/Ca in aragonite skeletons</div>
              <div class="k">Method</div><div class="v">ICP-OES, annual-resolution</div>
              <div class="k">Calibration</div><div class="v">vs. instrumental SST 1960– (r² &gt; 0.9)</div>
              <div class="k">Validation</div><div class="v">HadCRUT5, NOAA ERSSTv5</div>
              <div class="k">Divergence</div><div class="v">Pre-1850 — where hidden warming resides</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>

  <div class="footer">
    <div class="src">SOURCE · Sclerosponge SST reconstruction · <i>Nature Climate Change</i> (2024)</div>
    <div>Validated against HadCRUT5 &amp; NOAA ERSSTv5 across the instrumental era</div>
    <div class="doi">case-env-climate-sclerosponge-thermometry-1.5C</div>
  </div>

</div>

<script>
/* ---------- Build the centerpiece SVG line chart ---------- */
(function(){
  const svg = document.getElementById('tempchart');
  const W = 1480, H = 540;
  const M = { l: 70, r: 40, t: 30, b: 60 };
  const iw = W - M.l - M.r;
  const ih = H - M.t - M.b;

  // Synthetic but plausible reconstruction series (anomaly relative to 1700-1790 mean, °C)
  // Years 1700..2023 sampled every 3 years
  const start = 1700, end = 2023;
  const data = [];
  // Helper deterministic noise
  function n(seed){ const x = Math.sin(seed*12.9898)*43758.5453; return (x - Math.floor(x)) - 0.5; }

  for (let y = start; y <= end; y += 3) {
    const t = (y - start);
    let v;
    if (y < 1790) {
      // Stable near-zero with small variability
      v = 0 + 0.06 * n(y);
    } else if (y < 1850) {
      // Onset of warming
      v = ((y - 1790) / 60) * 0.45 + 0.07 * n(y);
    } else if (y < 1900) {
      // Already ~0.5 by 1850-1900
      v = 0.45 + ((y - 1850)/50)*0.10 + 0.08 * n(y);
    } else if (y < 1960) {
      // Gradual warming + volcanic dips
      let base = 0.55 + ((y-1900)/60)*0.30;
      // Volcanic cooling around 1815 (already past), 1883 (Krakatoa, past), 1902 Pelée, 1912 Katmai, 1963 Agung start
      if (Math.abs(y-1903)<3) base -= 0.10;
      if (Math.abs(y-1913)<3) base -= 0.08;
      v = base + 0.07 * n(y);
    } else if (y < 2000) {
      // Acceleration
      let base = 0.85 + ((y-1960)/40)*0.45;
      if (Math.abs(y-1964)<3) base -= 0.10; // Agung
      if (Math.abs(y-1992)<3) base -= 0.10; // Pinatubo
      v = base + 0.06 * n(y);
    } else {
      // Steep rise crossing 1.5 in early 2020s
      let base = 1.30 + ((y-2000)/23)*0.40;
      v = base + 0.05 * n(y);
    }
    data.push({ y, v });
  }

  const xs = data.map(d=>d.y), vs = data.map(d=>d.v);
  const xMin = start, xMax = end;
  const yMin = -0.3, yMax = 2.0;
  const x = yr => M.l + (yr - xMin)/(xMax-xMin) * iw;
  const y = vv => M.t + (1 - (vv - yMin)/(yMax-yMin)) * ih;

  const NS = 'http://www.w3.org/2000/svg';
  function el(tag, attrs, parent){
    const e = document.createElementNS(NS, tag);
    for (const k in attrs) e.setAttribute(k, attrs[k]);
    (parent||svg).appendChild(e);
    return e;
  }

  // Defs: warm gradient for line color
  const defs = el('defs', {});
  // Vertical area gradient
  const grad = el('linearGradient', {id:'areaG', x1:0, y1:0, x2:0, y2:1}, defs);
  el('stop', {offset:'0%', 'stop-color':'#c1272d', 'stop-opacity':'0.35'}, grad);
  el('stop', {offset:'55%', 'stop-color':'#e76f51', 'stop-opacity':'0.18'}, grad);
  el('stop', {offset:'100%', 'stop-color':'#155e8b', 'stop-opacity':'0.05'}, grad);

  // Horizontal warm-cool gradient for line stroke (cool early, warm late)
  const lg = el('linearGradient', {id:'lineG', x1:0, y1:0, x2:1, y2:0}, defs);
  el('stop', {offset:'0%',  'stop-color':'#0a3554'}, lg);
  el('stop', {offset:'45%', 'stop-color':'#155e8b'}, lg);
  el('stop', {offset:'70%', 'stop-color':'#e76f51'}, lg);
  el('stop', {offset:'100%','stop-color':'#c1272d'}, lg);

  // Plot background bands for thresholds
  // 1.5 °C zone
  el('rect', {x:M.l, y:y(2.0), width:iw, height: y(1.5)-y(2.0),
              fill:'#c1272d', 'fill-opacity':0.06}, svg);
  // pre-industrial band (-0.2..0.2)
  el('rect', {x:M.l, y:y(0.2), width:iw, height: y(-0.2)-y(0.2),
