const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({
    viewport: { width: 1600, height: 2263 },
    deviceScaleFactor: 2,
  });
  await page.goto('file:///app/output/poster.html', { waitUntil: 'networkidle' });
  // Wait for chart to render
  await page.waitForFunction(() => window.__chartReady === true, null, { timeout: 10000 });
  await page.waitForTimeout(500);

  await page.locator('.poster').screenshot({
    path: '/app/output/final_poster.png',
    type: 'png',
  });
  console.log('Screenshot saved to /app/output/final_poster.png');
  await browser.close();
})();

